package com.italiano2774.nativeapp;
import android.os.Bundle;import android.view.*;import android.widget.TextView;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.recyclerview.widget.LinearLayoutManager;import androidx.recyclerview.widget.RecyclerView;import com.google.android.material.button.MaterialButtonToggleGroup;import java.util.*;
public class ReadingFragment extends Fragment{
    private ReadingRepository repo;private ReadingAdapter adapter;private ProgressStore progress;private ReadingComprehensibilityEngine engine;private TextView stats;private String level="REC";
    @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){View v=i.inflate(R.layout.fragment_reading,c,false);repo=ReadingRepository.get(requireContext());progress=new ProgressStore(requireContext());engine=new ReadingComprehensibilityEngine(WordRepository.get(requireContext()),progress);stats=v.findViewById(R.id.text_reading_stats);RecyclerView rv=v.findViewById(R.id.recycler_readings);rv.setLayoutManager(new LinearLayoutManager(requireContext()));adapter=new ReadingAdapter(progress,engine,p->((MainActivity)requireActivity()).openReading(p.id));rv.setAdapter(adapter);MaterialButtonToggleGroup g=v.findViewById(R.id.group_read_level);g.addOnButtonCheckedListener((group,id,checked)->{if(!checked)return;level=id==R.id.button_read_a1?"A1":(id==R.id.button_read_a2?"A2":(id==R.id.button_read_b1?"B1":"REC"));refresh();});g.check(R.id.button_read_recommended);refresh();return v;}
    private void refresh(){List<ReadingPassage> list;if("REC".equals(level)){list=engine.recommended(repo.all());int ideal=0;for(ReadingPassage p:list){int c=engine.score(p).coverage;if(c>=90&&c<=98)ideal++;}stats.setText("按你的已掌握词动态排序 · 90–98% 已知词最适合精读 · 当前理想材料 "+ideal+"篇");}else{list=repo.byLevel(level);int sum=0;for(ReadingPassage p:list)sum+=engine.score(p).coverage;stats.setText(level+" 共 "+list.size()+"篇 · 平均已知词 "+(list.isEmpty()?0:sum/list.size())+"% · 阅读理解 "+(progress.auxiliaryAttempts("reading")==0?"尚未测试":(progress.auxiliaryAccuracy("reading")+"%")));}adapter.submit(list);}
}
